INSERT INTO `startup_strings_dbc` VALUES (1,'MSG_TITLE_WOW','World of Warcraft','','World of Warcraft','','','','','','','','','','','','','',16712190),(2,'MSG_GX_INIT_FAILED_D3D','World of Warcraft was unable to start up 3D acceleration. Please make sure DirectX 9.0c is installed and your video drivers are up-to-date.','','World of Warcraft n\'a pu lancer l\'accélération 3D. Assurez-vous que DirectX 9.0c est installé et que vos pilotes graphiques sont à jour.','','','','','','','','','','','','','',16712190),(3,'MSG_GX_INIT_FAILED','World of Warcraft was unable to start up 3D acceleration.','','World of Warcraft n\'a pu lancer l\'accélération 3D.','','','','','','','','','','','','','',16712190),(4,'MSG_HW_UNSUPPORTED','Your 3D accelerator card is not supported by World of Warcraft. Please install a 3D accelerator card with dual-TMU support.','','Votre carte accélératrice 3D n\'est pas compatible avec World of Warcraft. Veuillez installer une carte accélératrice 3D avec deux unités de mappage des textures (TMU).','','','','','','','','','','','','','',16712190),(5,'MSG_HW_CHANGED','Hardware changed.  Reload default settings?','','Matériel modifié. Charger les paramètres par défaut ?','','','','','','','','','','','','','',16712190),(9,'MSG_GLUEXML_UI_CORRUPT','Your login interface files are corrupt.  Please reinstall the game.','','Vos fichiers d\'interface de connexion sont corrompus. Veuillez réinstaller le jeu.','','','','','','','','','','','','','',16712190),(10,'MSG_FRAMEXML_UI_CORRUPT','Your game interface files are corrupt.  Please remove your Interface\\FrameXML folder.','','Vos fichiers d\'interface sont corrompus. Veuillez supprimer votre dossier Interface\\Frame\\XML.','','','','','','','','','','','','','',16712190),(11,'MSG_GX_NO_DEVICE','Failed to find a suitable display device.  Exiting program.','','Impossible de trouver un dispositif d\'affichage adéquat. Fermeture du programme.','','','','','','','','','','','','','',16712190),(12,'MSG_REMOTE_DESKTOP','Running World of Warcraft through a Remote Desktop connection is not supported.  Exiting program.','','World of Warcraft n\'est pas conçu pour fonctionner via une connexion de bureau virtuel distant. Fermeture du programme.','','','','','','','','','','','','','',16712190);
